//! Cargo-driven `dmime.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", None),
        o => panic!("dmime-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/directx/wine/dmime/dmime_r.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:c:dxguid", "engine:uuid", "engine:oldnames", "import:dsound", "import:ole32", "import:user32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "x86_64" => &["dll/directx/wine/dmime/dmime_r.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:c:dxguid", "engine:uuid", "engine:oldnames", "import:dsound", "import:ole32", "import:user32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "aarch64" => &["dll/directx/wine/dmime/dmime_r.o", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "engine:c:dxguid", "engine:uuid", "engine:oldnames", "import:dsound", "import:ole32", "import:user32", "import:advapi32", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/directx/wine/dmime",
        "dll/directx/wine/dmime",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "dll/directx/wine/dmime/../dmusic",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x600",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x600",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("dmime_shims", &["dll/directx/wine/dmime/audiopath.c", "dll/directx/wine/dmime/dmime_main.c", "dll/directx/wine/dmime/graph.c", "dll/directx/wine/dmime/lyricstrack.c", "dll/directx/wine/dmime/markertrack.c", "dll/directx/wine/dmime/midi.c", "dll/directx/wine/dmime/paramcontroltrack.c", "dll/directx/wine/dmime/performance.c", "dll/directx/wine/dmime/segment.c", "dll/directx/wine/dmime/segmentstate.c", "dll/directx/wine/dmime/segtriggertrack.c", "dll/directx/wine/dmime/seqtrack.c", "dll/directx/wine/dmime/sysextrack.c", "dll/directx/wine/dmime/tempotrack.c", "dll/directx/wine/dmime/timesigtrack.c", "dll/directx/wine/dmime/wavetrack.c", "dll/directx/wine/dmusic/band.c", "dll/directx/wine/dmusic/dmobject.c", "dll/directx/wine/dmusic/wave.c"])
        .rc("dll/directx/wine/dmime/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/directx/wine/dmime/dmime.spec", "dmime.dll")
        .import_lib("dll/directx/wine/dsound/dsound.spec", "dsound.dll", "dsound")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
